update tea_member
set m_passwd=#{m_passwd}, m_tel=#{m_tel},m_phone=#{m_phone},m_email=#{m_email},m_zipno=#{m_zipno}, m_addr=#{m_addr}, m_rsms=#{m_rsms},m_remail=#{m_remail},m_birth=#{m_birth}
